package main

import (
	"fmt"
)

func main() {
	var s, x int64
	fmt.Scan(&s, &x)

	if s < x || (s-x)%2 != 0 {
		fmt.Println(0)
		return
	}

	d := (s - x) / 2
	if (d & x) != 0 {
		fmt.Println(0)
		return
	}

	count := 0
	for i := 0; i < 60; i++ {
		if (x>>i)&1 == 1 {
			count++
		}
	}

	result := int64(1) << uint(count)
	if d == 0 {
		result -= 2
	}
	if result < 0 {
		result = 0
	}
	fmt.Println(result)
}
